import{_ as e,c as i,o,a3 as n}from"./chunks/framework.CoV49S2T.js";const m=JSON.parse('{"title":"Introducción","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/introduction.md","filePath":"es/guide/introduction.md","lastUpdated":1787284674000}'),r={name:"es/guide/introduction.md"};function s(t,a,l,c,d,u){return o(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="introduccion" tabindex="-1">Introducción <a class="header-anchor" href="#introduccion" aria-label="Permalink to &quot;Introducción&quot;">​</a></h1><h2 id="acerca-de-clipboxai" tabindex="-1">Acerca de ClipboxAI <a class="header-anchor" href="#acerca-de-clipboxai" aria-label="Permalink to &quot;Acerca de ClipboxAI&quot;">​</a></h2><p><strong>ClipboxAI</strong> es un gestor de portapapeles inteligente para macOS. Cada vez que copia texto, código o un enlace, se guarda en un historial buscable en su barra de menú. Con un clic — o de forma totalmente automática — puede ejecutar una acción sobre ese fragmento: resumirlo, traducirlo, ordenarlo o enviarlo a un modelo de IA en la nube.</p><p>Se basa en dos tipos de herramientas:</p><ul><li><strong>Herramientas locales integradas</strong> que se ejecutan completamente en su Mac, sin conexión de red.</li><li><strong>Acciones de IA</strong> que llaman a un modelo en la nube que usted configura (su propia API key, almacenada en el Keychain del sistema).</li></ul><h2 id="funciones-principales" tabindex="-1">Funciones principales <a class="header-anchor" href="#funciones-principales" aria-label="Permalink to &quot;Funciones principales&quot;">​</a></h2><h3 id="📋-historial-del-portapapeles" tabindex="-1">📋 Historial del portapapeles <a class="header-anchor" href="#📋-historial-del-portapapeles" aria-label="Permalink to &quot;📋 Historial del portapapeles&quot;">​</a></h3><p>Todo lo que copia se captura automáticamente y se guarda en un historial buscable. Vuelva a cualquier fragmento anterior desde la barra de menú — nada de fragmentos perdidos.</p><h3 id="⚡-sugerencias-inteligentes" tabindex="-1">⚡ Sugerencias inteligentes <a class="header-anchor" href="#⚡-sugerencias-inteligentes" aria-label="Permalink to &quot;⚡ Sugerencias inteligentes&quot;">​</a></h3><p>ClipboxAI sugiere las acciones más relevantes para el fragmento actual. Acepte una sugerencia o explore la lista completa de herramientas.</p><h3 id="🛠️-herramientas-locales-integradas" tabindex="-1">🛠️ Herramientas locales integradas <a class="header-anchor" href="#🛠️-herramientas-locales-integradas" aria-label="Permalink to &quot;🛠️ Herramientas locales integradas&quot;">​</a></h3><p>Sin conexión, privadas, instantáneas:</p><ul><li><strong>Extraer enlaces</strong> — extrae todas las URL de un bloque de texto.</li><li><strong>Contar estadísticas</strong> — recuento de palabras, caracteres, líneas y frases.</li><li><strong>Colapsar líneas en blanco</strong> — ordena el texto pegado en un solo paso.</li></ul><p>Con el tiempo se pueden añadir más herramientas locales — nunca salen de su dispositivo.</p><h3 id="✨-acciones-de-ia" tabindex="-1">✨ Acciones de IA <a class="header-anchor" href="#✨-acciones-de-ia" aria-label="Permalink to &quot;✨ Acciones de IA&quot;">​</a></h3><p>Envíe el fragmento actual a un modelo en la nube para:</p><ul><li><strong>Resumir</strong> artículos y hilos largos.</li><li><strong>Traducir</strong> entre idiomas.</li><li><strong>Reescribir / pulir</strong> el tono y la claridad.</li><li>Ejecutar cualquier acción del <strong>Marketplace</strong>.</li></ul><h3 id="🛒-marketplace-de-acciones" tabindex="-1">🛒 Marketplace de acciones <a class="header-anchor" href="#🛒-marketplace-de-acciones" aria-label="Permalink to &quot;🛒 Marketplace de acciones&quot;">​</a></h3><p>Explore acciones de IA creadas por la comunidad e instálelas con un clic mediante un enlace profundo (<code>clipboxai://install?action=&lt;id&gt;</code>). Las categorías incluyen Escritura, Desarrollador, Productividad, Traducir, Redes sociales y Analítica.</p><h3 id="🔒-privado-por-diseno" tabindex="-1">🔒 Privado por diseño <a class="header-anchor" href="#🔒-privado-por-diseno" aria-label="Permalink to &quot;🔒 Privado por diseño&quot;">​</a></h3><p>Su historial del portapapeles permanece en su dispositivo. La IA en la nube es <strong>opcional</strong>: cuando se activa, el contenido se envía solo al proveedor que <em>usted</em> elija, usando una API key almacenada en su Keychain. Nunca recibimos ni almacenamos sus fragmentos, y no hay analítica ni telemetría.</p><h2 id="requisitos-del-sistema" tabindex="-1">Requisitos del sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to &quot;Requisitos del sistema&quot;">​</a></h2><ul><li><strong>Sistema operativo</strong>: macOS 14 Sonoma o posterior</li><li><strong>CPU</strong>: Apple Silicon (serie M) o Intel (64 bits)</li><li><strong>Memoria</strong>: 4 GB de RAM mínimo, 8 GB recomendado</li><li><strong>Almacenamiento</strong>: ~50 MB para la instalación</li><li><strong>Para la IA en la nube</strong>: una API key de un proveedor compatible (DeepSeek, MiniMax, Zhipu GLM, Kimi, Mistral, Ollama, OpenAI, Anthropic o Gemini)</li></ul><h2 id="idiomas-compatibles" tabindex="-1">Idiomas compatibles <a class="header-anchor" href="#idiomas-compatibles" aria-label="Permalink to &quot;Idiomas compatibles&quot;">​</a></h2><p>La aplicación y este sitio son compatibles con 7 idiomas: inglés, chino simplificado (简体中文), chino tradicional (繁體中文), japonés (日本語), alemán, español y francés.</p><h2 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h2><p>Si es nuevo en ClipboxAI, comience con la <a href="/es/guide/installation.html">Guía de instalación</a> para poner la aplicación en marcha en su Mac y, a continuación, lea <a href="/es/guide/usage.html">Uso</a> para aprender cómo funcionan las acciones.</p>',27)])])}const h=e(r,[["render",s]]);export{m as __pageData,h as default};
